// Master 28 States Dictionary
const STATES_DATA = {
  'west-bengal': WEST_BENGAL_DATA,
  'andhra-pradesh': ANDHRA_PRADESH_DATA,
  'arunachal-pradesh': ARUNACHAL_PRADESH_DATA,
  'assam': ASSAM_DATA,
  'bihar': BIHAR_DATA,
  'chhattisgarh': CHHATTISGARH_DATA,
  'goa': GOA_DATA,
  'gujarat': GUJARAT_DATA,
  'haryana': HARYANA_DATA,
  'himachal-pradesh': HIMACHAL_PRADESH_DATA,
  'jharkhand': JHARKHAND_DATA,
  'karnataka': KARNATAKA_DATA,
  'kerala': KERALA_DATA,
  'madhya-pradesh': MADHYA_PRADESH_DATA,
  'maharashtra': MAHARASHTRA_DATA,
  'manipur': MANIPUR_DATA,
  'meghalaya': MEGHALAYA_DATA,
  'mizoram': MIZORAM_DATA,
  'nagaland': NAGALAND_DATA,
  'odisha': ODISHA_DATA,
  'punjab': PUNJAB_DATA,
  'rajasthan': RAJASTHAN_DATA,
  'sikkim': SIKKIM_DATA,
  'tamil-nadu': TAMIL_NADU_DATA,
  'telangana': TELANGANA_DATA,
  'tripura': TRIPURA_DATA,
  'uttar-pradesh': UTTAR_PRADESH_DATA,
  'uttarakhand': UTTARAKHAND_DATA,
};

// State aliases and lookup mapping
const STATE_ALIASES = {
  'wb': 'west-bengal',
  'bengal': 'west-bengal',
  'ap': 'andhra-pradesh',
  'ar': 'arunachal-pradesh',
  'as': 'assam',
  'br': 'bihar',
  'cg': 'chhattisgarh',
  'ga': 'goa',
  'gj': 'gujarat',
  'hr': 'haryana',
  'hp': 'himachal-pradesh',
  'jh': 'jharkhand',
  'ka': 'karnataka',
  'kl': 'kerala',
  'mp': 'madhya-pradesh',
  'mh': 'maharashtra',
  'mn': 'manipur',
  'ml': 'meghalaya',
  'mz': 'mizoram',
  'nl': 'nagaland',
  'od': 'odisha',
  'or': 'odisha',
  'pb': 'punjab',
  'rj': 'rajasthan',
  'sk': 'sikkim',
  'tn': 'tamil-nadu',
  'ts': 'telangana',
  'tg': 'telangana',
  'tr': 'tripura',
  'up': 'uttar-pradesh',
  'uk': 'uttarakhand',
  'ut': 'uttarakhand'
};

// Utility function to fetch state data based on state key or URL parameter
function getStateData(stateKey) {
  if (!stateKey) return STATES_DATA['west-bengal'];
  const key = stateKey.trim().toLowerCase().replace(/_/g, '-');
  
  if (STATES_DATA[key]) return STATES_DATA[key];
  if (STATE_ALIASES[key] && STATES_DATA[STATE_ALIASES[key]]) return STATES_DATA[STATE_ALIASES[key]];
  
  // Search by state name
  const byName = Object.values(STATES_DATA).find(s => 
    s.state.toLowerCase() === key || s.slug === key
  );
  if (byName) return byName;
  
  return STATES_DATA['west-bengal'];
}

// Utility lookup functions for district
function getDistrictBySlug(slug, stateHint) {
  if (!slug) return null;
  const normalized = slug.trim().toLowerCase();

  // 1. If state hint is provided, search that state first
  if (stateHint) {
    const hintData = getStateData(stateHint);
    if (hintData && hintData.districts) {
      const match = hintData.districts.find(d => 
        d.slug.toLowerCase() === normalized || 
        d.name.toLowerCase() === normalized || 
        d.id.toLowerCase() === normalized
      );
      if (match) {
        return {
          ...match,
          stateName: hintData.state,
          stateSlug: hintData.slug
        };
      }
    }
  }

  // 2. Search across all 28 states
  for (const s of Object.values(STATES_DATA)) {
    const match = s.districts.find(d => 
      d.slug.toLowerCase() === normalized || 
      d.name.toLowerCase() === normalized || 
      d.id.toLowerCase() === normalized
    );
    if (match) {
      return {
        ...match,
        stateName: s.state,
        stateSlug: s.slug
      };
    }
  }

  return null;
}

function searchDistricts(query, stateKey) {
  const currentDataset = getStateData(stateKey);
  if (!query || !query.trim()) return currentDataset.districts;
  const term = query.trim().toLowerCase();
  return currentDataset.districts.filter(d => 
    d.name.toLowerCase().includes(term) ||
    d.headquarters.toLowerCase().includes(term) ||
    (d.tagline && d.tagline.toLowerCase().includes(term)) ||
    (d.knownFor && d.knownFor.toLowerCase().includes(term)) ||
    (d.attractions && d.attractions.some(a => a.name.toLowerCase().includes(term) || a.location.toLowerCase().includes(term)))
  );
}

// Expose on global window object for accessibility across scripts
if (typeof window !== 'undefined') {
  window.WEST_BENGAL_DATA = STATES_DATA['west-bengal'];
  window.ANDHRA_PRADESH_DATA = STATES_DATA['andhra-pradesh'];
  window.STATES_DATA = STATES_DATA;
  window.getStateData = getStateData;
  window.getDistrictBySlug = getDistrictBySlug;
  window.searchDistricts = searchDistricts;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    STATES_DATA,
    getStateData,
    getDistrictBySlug,
    searchDistricts,
    ...STATES_DATA
  };
}

export {
  STATES_DATA,
  getStateData,
  getDistrictBySlug,
  searchDistricts
};
export default STATES_DATA;
